ALTER TABLE public.care_circles ADD COLUMN preferences jsonb NOT NULL DEFAULT '{}'::jsonb;
ALTER TABLE public.reminders ADD COLUMN snooze_minutes integer NOT NULL DEFAULT 0, ADD COLUMN date_override date, ADD COLUMN deleted_at timestamptz, ADD COLUMN updated_at timestamptz NOT NULL DEFAULT now();
CREATE TABLE public.care_members (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), circle_id uuid NOT NULL REFERENCES public.care_circles(id) ON DELETE CASCADE, telegram_user_id bigint NOT NULL, member_name text NOT NULL DEFAULT 'Family member', role text NOT NULL DEFAULT 'viewer' CHECK (role IN ('owner','editor','viewer')), direct_chat_id bigint, notify_order integer NOT NULL DEFAULT 0, revoked_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(circle_id,telegram_user_id));
GRANT ALL ON public.care_members TO service_role;
ALTER TABLE public.care_members ENABLE ROW LEVEL SECURITY;
CREATE INDEX care_members_circle_idx ON public.care_members(circle_id);
CREATE INDEX care_members_user_idx ON public.care_members(telegram_user_id);
INSERT INTO public.care_members(circle_id,telegram_user_id,role,direct_chat_id) SELECT c.id,u.telegram_user_id,'owner',CASE WHEN c.telegram_chat_id>0 THEN c.telegram_chat_id ELSE NULL END FROM public.care_circles c JOIN LATERAL (SELECT telegram_user_id FROM public.telegram_updates WHERE chat_id=c.telegram_chat_id AND telegram_user_id IS NOT NULL ORDER BY created_at LIMIT 1) u ON true ON CONFLICT DO NOTHING;
CREATE TABLE public.care_access_codes (code_hash text PRIMARY KEY, member_id uuid NOT NULL REFERENCES public.care_members(id) ON DELETE CASCADE, expires_at timestamptz NOT NULL, used_at timestamptz);
GRANT ALL ON public.care_access_codes TO service_role;
ALTER TABLE public.care_access_codes ENABLE ROW LEVEL SECURITY;
CREATE INDEX care_access_member_idx ON public.care_access_codes(member_id);
CREATE TABLE public.care_sessions (token_hash text PRIMARY KEY, member_id uuid NOT NULL REFERENCES public.care_members(id) ON DELETE CASCADE, expires_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
GRANT ALL ON public.care_sessions TO service_role;
ALTER TABLE public.care_sessions ENABLE ROW LEVEL SECURITY;
CREATE INDEX care_sessions_member_idx ON public.care_sessions(member_id);
CREATE TABLE public.care_invitations (code_hash text PRIMARY KEY,circle_id uuid NOT NULL REFERENCES public.care_circles(id) ON DELETE CASCADE,role text NOT NULL CHECK(role IN ('editor','viewer')),expires_at timestamptz NOT NULL,used_at timestamptz,created_by uuid NOT NULL REFERENCES public.care_members(id));
GRANT ALL ON public.care_invitations TO service_role;
ALTER TABLE public.care_invitations ENABLE ROW LEVEL SECURITY;
CREATE INDEX care_invitations_circle_idx ON public.care_invitations(circle_id);
CREATE INDEX care_invitations_creator_idx ON public.care_invitations(created_by);
CREATE TABLE public.care_occurrences (reminder_id uuid NOT NULL REFERENCES public.reminders(id) ON DELETE CASCADE,local_date date NOT NULL,circle_id uuid NOT NULL REFERENCES public.care_circles(id) ON DELETE CASCADE,state text NOT NULL DEFAULT 'pending' CHECK(state IN ('pending','done','postponed','help','declined')),postponed_minute integer,step integer NOT NULL DEFAULT 0,version integer NOT NULL DEFAULT 0,updated_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(reminder_id,local_date));
GRANT ALL ON public.care_occurrences TO service_role;
ALTER TABLE public.care_occurrences ENABLE ROW LEVEL SECURITY;
CREATE INDEX care_occurrences_circle_idx ON public.care_occurrences(circle_id,local_date);
CREATE TABLE public.care_routines (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),circle_id uuid NOT NULL REFERENCES public.care_circles(id) ON DELETE CASCADE,title text NOT NULL,local_time text NOT NULL,steps jsonb NOT NULL DEFAULT '[]'::jsonb,enabled boolean NOT NULL DEFAULT true,date_override date,progress jsonb NOT NULL DEFAULT '{}'::jsonb,updated_at timestamptz NOT NULL DEFAULT now());
GRANT ALL ON public.care_routines TO service_role;
ALTER TABLE public.care_routines ENABLE ROW LEVEL SECURITY;
CREATE INDEX care_routines_circle_idx ON public.care_routines(circle_id);
CREATE TABLE public.care_notes (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),circle_id uuid NOT NULL REFERENCES public.care_circles(id) ON DELETE CASCADE,label text NOT NULL,answer text NOT NULL,category text NOT NULL DEFAULT 'reassurance' CHECK(category IN ('person','object','reassurance','message')),phone text NOT NULL DEFAULT '',media_path text,media_kind text CHECK(media_kind IN ('photo','audio')),updated_at timestamptz NOT NULL DEFAULT now());
GRANT ALL ON public.care_notes TO service_role;
ALTER TABLE public.care_notes ENABLE ROW LEVEL SECURITY;
CREATE INDEX care_notes_circle_idx ON public.care_notes(circle_id);
CREATE TABLE public.care_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),circle_id uuid NOT NULL REFERENCES public.care_circles(id) ON DELETE CASCADE,reminder_id uuid REFERENCES public.reminders(id) ON DELETE SET NULL,idempotency_key text NOT NULL UNIQUE,kind text NOT NULL,label text NOT NULL,actor_name text NOT NULL DEFAULT 'Your Loved One',acknowledged_by uuid REFERENCES public.care_members(id),delivery text NOT NULL DEFAULT 'not_sent',escalated_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
GRANT ALL ON public.care_events TO service_role;
ALTER TABLE public.care_events ENABLE ROW LEVEL SECURITY;
CREATE INDEX care_events_circle_idx ON public.care_events(circle_id,created_at DESC);
CREATE INDEX care_events_reminder_idx ON public.care_events(reminder_id);
CREATE INDEX care_events_ack_idx ON public.care_events(acknowledged_by);
CREATE TABLE public.care_history (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),circle_id uuid NOT NULL REFERENCES public.care_circles(id) ON DELETE CASCADE,entity text NOT NULL,entity_id uuid NOT NULL,label text NOT NULL,before_value jsonb,after_version timestamptz NOT NULL,undone_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
GRANT ALL ON public.care_history TO service_role;
ALTER TABLE public.care_history ENABLE ROW LEVEL SECURITY;
CREATE INDEX care_history_circle_idx ON public.care_history(circle_id,created_at DESC);
CREATE OR REPLACE FUNCTION public.care_apply_action(p_circle uuid,p_reminder uuid,p_date date,p_action text,p_key text,p_actor text,p_minute integer,p_minutes integer DEFAULT 15) RETURNS jsonb LANGUAGE plpgsql SET search_path=public AS $$
DECLARE r public.reminders; o public.care_occurrences; e uuid; next_state text;
BEGIN
SELECT * INTO r FROM public.reminders WHERE id=p_reminder AND circle_id=p_circle AND deleted_at IS NULL FOR UPDATE;
IF NOT FOUND THEN RAISE EXCEPTION 'Reminder unavailable'; END IF;
IF r.date_override IS NOT NULL AND r.date_override<>p_date THEN RAISE EXCEPTION 'Wrong occurrence date'; END IF;
IF p_action NOT IN ('done','later','help','decline','repeat','step') THEN RAISE EXCEPTION 'Invalid action'; END IF;
IF p_action='later' AND (p_minutes<1 OR p_minutes>120 OR p_minute+p_minutes>1439 OR (r.critical AND (r.snooze_minutes=0 OR p_minutes>r.snooze_minutes))) THEN RAISE EXCEPTION 'Postponement not approved'; END IF;
INSERT INTO public.care_occurrences(reminder_id,local_date,circle_id,state) VALUES(p_reminder,p_date,p_circle,CASE WHEN r.confirmed_on=p_date THEN 'done' ELSE 'pending' END) ON CONFLICT DO NOTHING;
SELECT * INTO o FROM public.care_occurrences WHERE reminder_id=p_reminder AND local_date=p_date FOR UPDATE;
INSERT INTO public.care_events(circle_id,reminder_id,idempotency_key,kind,label,actor_name) VALUES(p_circle,p_reminder,p_key,p_action,r.title,p_actor) ON CONFLICT(idempotency_key) DO NOTHING RETURNING id INTO e;
IF e IS NULL THEN RETURN jsonb_build_object('duplicate',true,'state',o.state,'version',o.version); END IF;
IF o.state='done' AND p_action NOT IN ('repeat') THEN RETURN jsonb_build_object('state',o.state,'version',o.version); END IF;
next_state:=CASE p_action WHEN 'done' THEN 'done' WHEN 'later' THEN 'postponed' WHEN 'help' THEN 'help' WHEN 'decline' THEN 'declined' ELSE o.state END;
UPDATE public.care_occurrences SET state=next_state,postponed_minute=CASE WHEN p_action='later' THEN p_minute+p_minutes ELSE postponed_minute END,step=CASE WHEN p_action='step' THEN step+1 ELSE step END,version=version+1,updated_at=now() WHERE reminder_id=p_reminder AND local_date=p_date RETURNING * INTO o;
IF p_action='done' THEN UPDATE public.reminders SET confirmed_on=p_date,confirmed_at=now(),status='done',missed_streak=0,last_missed_on=NULL WHERE id=p_reminder; END IF;
RETURN jsonb_build_object('state',o.state,'version',o.version,'eventId',e);
END $$;
REVOKE ALL ON FUNCTION public.care_apply_action(uuid,uuid,date,text,text,text,integer,integer) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.care_apply_action(uuid,uuid,date,text,text,text,integer,integer) TO service_role;
CREATE OR REPLACE FUNCTION public.care_claim_access(p_hash text,p_token_hash text) RETURNS uuid LANGUAGE plpgsql SET search_path=public AS $$ DECLARE m uuid; BEGIN UPDATE public.care_access_codes SET used_at=now() WHERE code_hash=p_hash AND used_at IS NULL AND expires_at>now() RETURNING member_id INTO m; IF m IS NULL OR NOT EXISTS(SELECT 1 FROM public.care_members WHERE id=m AND revoked_at IS NULL) THEN RETURN NULL; END IF; INSERT INTO public.care_sessions(token_hash,member_id,expires_at) VALUES(p_token_hash,m,now()+interval '12 hours'); RETURN m; END $$;
REVOKE ALL ON FUNCTION public.care_claim_access(text,text) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.care_claim_access(text,text) TO service_role;